// Format bookings for display
const bookings = items;

if (bookings.length === 0) {
  return [{
    json: {
      message: "📭 No pending or confirmed bookings"
    }
  }];
}

let message = "🎵 **DJ Bookings**\n\n";

for (const booking of bookings) {
  const date = new Date(booking.json.event_date).toLocaleDateString();
  const status = booking.json.status.toUpperCase();
  const venue = booking.json.venue_name || 'TBD';
  const price = booking.json.quoted_price ? `£${booking.json.quoted_price}` : 'Not quoted';

  message += `📅 **${date}** - ${status}\n`;
  message += `📍 ${venue}\n`;
  message += `💰 ${price}\n`;
  message += `👤 ${booking.json.client_name}\n`;
  message += `📞 ${booking.json.client_phone || 'No phone'}\n`;
  message += `\n`;
}

return [{
  json: {
    message: message,
    bookings: bookings
  }
}];

// Check if date is available
const bookings = items;
const requestedDate = $node["Wait for Date Input"].json.message.text;

if (bookings.length === 0) {
  return [{
    json: {
      available: true,
      date: requestedDate,
      message: `✅ **AVAILABLE**\n\n📅 ${requestedDate} is free!\n\nWould you like to:\n1. Create a quote\n2. Block the date\n3. Go back to menu`
    }
  }];
} else {
  const booking = bookings[0].json;
  return [{
    json: {
      available: false,
      date: requestedDate,
      message: `❌ **NOT AVAILABLE**\n\n📅 ${requestedDate} is already booked\n\n📍 ${booking.venue_name || 'Venue TBD'}\n👤 ${booking.client_name}\n📊 Status: ${booking.status}`
    }
  }];
}

// Parse quote details
const input = items[0].json.message.text;
const lines = input.split('\n').map(l => l.trim()).filter(l => l);

if (lines.length < 5) {
  return [{
    json: {
      error: true,
      message: "❌ Missing information. Please provide all 6 items."
    }
  }];
}

// Base pricing
const basePrices = {
  wedding: 600,
  birthday: 400,
  corporate: 750,
  private: 350
};

const clientName = lines[0];
const eventDate = lines[1];
const eventType = lines[2].toLowerCase();
const duration = parseInt(lines[3]);
const venueName = lines[4];
const specialRequests = lines[5] || 'None';

// Calculate price
let basePrice = basePrices[eventType] || 400;
let additionalHours = Math.max(0, duration - 4);
let totalPrice = basePrice + (additionalHours * 75);

// Add-ons
if (specialRequests.toLowerCase().includes('lighting')) {
  totalPrice += 150;
}
if (specialRequests.toLowerCase().includes('smoke')) {
  totalPrice += 50;
}
if (specialRequests.toLowerCase().includes('photo')) {
  totalPrice += 200;
}

return [{
  json: {
    error: false,
    client_name: clientName,
    event_date: eventDate,
    event_type: eventType,
    duration: duration,
    venue_name: venueName,
    special_requests: specialRequests,
    base_price: basePrice,
    total_price: totalPrice,
    breakdown: {
      base: basePrice,
      extra_hours: additionalHours * 75,
      addons: totalPrice - basePrice - (additionalHours * 75)
    }
  }
}];

