// Format upcoming gigs
const gigs = items;

if (gigs.length === 0) {
  return [{
    json: {
      message: "📭 No upcoming gigs scheduled"
    }
  }];
}

let message = "🎵 **Upcoming DJ Gigs**\n\n";
let totalRevenue = 0;

for (const gig of gigs) {
  const date = new Date(gig.json.event_date);
  const daysUntil = Math.ceil((date - new Date()) / (1000 * 60 * 60 * 24));
  const dateStr = date.toLocaleDateString('en-GB', { weekday: 'short', day: 'numeric', month: 'short' });

  message += `📅 **${dateStr}** (${daysUntil} days)\n`;
  message += `${gig.json.event_type.toUpperCase()} - ${gig.json.status.toUpperCase()}\n`;
  message += `📍 ${gig.json.venue_name}\n`;
  message += `👤 ${gig.json.client_name}\n`;
  message += `💰 £${gig.json.quoted_price}\n`;
  message += `⏱️ ${gig.json.duration_hours} hours\n`;
  message += `\n`;

  if (gig.json.status === 'confirmed') {
    totalRevenue += gig.json.quoted_price;
  }
}

message += `\n💵 **Total Confirmed Revenue:** £${totalRevenue}`;

return [{
  json: {
    message: message,
    total_gigs: gigs.length,
    total_revenue: totalRevenue
  }
}];
